[3221]={"Habla con Renferrel",{"Habla con el boticario Renferrel en El Sepulcro."}},
[3261]={"Jorn Visioceleste",{"Habla con Jorn Visioceleste en el Campamento Taurajo."}},
[3281]={"La plata robada",{"Llévale la plata robada a Gazrog en El Cruce."}},
[3301]={"Mura Runatótem",{"Habla con Mura Runatótem en El Sepulcro."}},
