[6721]={"El camino del cazador",{"Habla con Dazalar en Dolanaar."}},
[6722]={"El camino del cazador",{"Habla con Dazalar en Dolanaar."}},
[6741]={"¡Más botines!",nil},
[6761]={"La nueva frontera",{"Ve a Darnassus, al Enclave Cenarion y habla con Mathrengyl Garroso."}},
[6762]={nil,{"Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Rabine Saturna. Claro de la Luna se encuentra entre Frondavil y Cuna del Invierno; para llegar, tienes que seguir el camino que sale del Bastión de los Fauces de Madera."}},
[6781]={"Más restos de armadura",nil},
[6801]={"Lokholar, el Señor del Hielo",nil},
[6804]={"Agua envenenada",{"Aplica el aspecto de Neptulon a los elementales infectados de las Tierras de la Peste del Este. Lleva 12 de sus brazales de vínculo y el aspecto de Neptulon al duque Hydraxis a Azshara."}},
[6805]={"Sirocosos y reptarenas",{"Mata a 15 agitadores sirocosos y 15 estruendores del desierto y vuelve a ver al duque Hydraxis a Azshara."}},
[6821]={"Ojo de brasadivino",{"Lleva el ojo del Piroguardián brasadivino al duque Hydraxis a Azshara."}},
[6822]={"El Núcleo de Magma",{"Mata a 1 Señor del Fuego, 1 gigante fundido, 1 canino del Núcleo y 1 marea de lava y ve a ver al duque Hydraxis a Azshara."}},
[6823]={"Agente de Hydraxis",{"Consigue una mención de honor de los Señores del Agua y habla con el duque Hydraxis en Azshara."}},
[6824]={"Las manos de los enemigos",{"Lleva las manos de Lucifron, Sulfuron, Gehennas y Shazzrah al duque Hydraxis a Azshara."}},
[6825]={"La llamada del aire: flota de Guse",nil},
[6826]={"La llamada del aire: flota de Jeztor",nil},
[6827]={"La llamada del aire: flota de Mulverick",nil},
[6844]={"Umber, el archivista",{"Lleva el objeto recubierto de silítido a Umber, el archivista del Círculo Cenarion, en la aldea de Amparo de la Noche, en el Claro de la Luna."}},
[6845]={"El descubrimiento de los secretos del pasado",{"Habla con el rabino Saturna en el poblado Amparo de la Noche, en Claro de la Luna."}},
[6846]={"¡Al ataque!",nil},
[6881]={"Ivus, el Señor del Bosque",nil},
[6921]={"Entre ruinas",{"Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno."}},
[6922]={"Barón Aquanis",{"Llévale el extraño globo de agua a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno."}},
[6941]={"La llamada del aire: la flota de Vipore",nil},
[6942]={"La llamada del aire: la flota de Slidore",nil},
[6943]={"La llamada del aire: la flota de Ichman",nil},
[6981]={"El fragmento brillante",{"Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento brillante.","","Entrega el fragmento como se te indique."}},
[6982]={"Suministros de Dentefrío",{"Lleva 10 cajas de suministros de Dentefrío al intendente de la Alianza en Dun Baldar."}},
[6985]={"Suministros de Ferrohondo",{"Lleva 10 cajas de suministros de Ferrohondo al intendente de la Horda en el Bastión Lobo Gélido."}},
[7001]={"Establos vacíos",{"Encuentra a un Lobo Gélido en el Valle de Alterac. Usa el collar Lobo Gélido cuando estés junto a él para domarlo. Cuando lo consigas, te seguirá hasta el maestro de establos de los Lobo Gélido. Habla con el maestro de establos para ganarte el crédito por la captura."}},
[7002]={"Arneses para carneros de montar",nil},
[7003]={"Gigantes reducidos",{"Utiliza el Ultra-reductor de Zorbin para encoger a cualquier gigante que encuentres en Feralas a un tamaño más manejable. Lleva 15 residuos de miniaturización encontrados en las versiones encogidas de los gigantes a Zorbin Ventipnotizador, al embarcadero de La Costa Olvidada de Feralas."}},
[7026]={"Arneses para carneros de montar",nil},
[7027]={"Establos vacíos",{"Encuentra un carnero de Alterac en el Valle de Alterac. Usa la collera de entrenamiento Pico Tormenta cuando estés junto al carnero de Alterac para domarlo. Cuando lo consigas, te seguirá hasta el maestro de establos. Habla con el maestro de establos para ganarte el crédito por la captura.|n"}},
[7028]={"Los males de Maraudón",{"Recoge 25 tallas de cristal terádrico y llévaselas a Willow a Desolace."}},
[7029]={"La corrupción de Lenguavil",{"Llena el vial cerúleo cubierto en el estanque naranja de Maraudon.","","Aplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico.","","Cura 8 plantas eliminando su sucesor tóxico e informa a Vark Marca de Guerra en la Aldea Cazasombras."}},
[7041]={"La corrupción de Lenguavil",{"Llena el vial revestido en el estanque naranja de Maraudon.","","Aplica el líquido a la hiedra tallovil para que emerja el vástago tóxico.","","Cura 8 plantas eliminando su vástago tóxico e informa a Talendria en Punta de Nijel."}},
[7044]={"Leyendas de Maraudón",{"Recupera las 2 partes del Cetro de Celebras: la vara y el diamante Celebrian.","","Encuentra el modo de hablar con Celebras."}},
[7046]={"El cetro de Celebras",{"Ayuda a Celebras el Redimido mientras reconstruye el cetro de Celebras.","","Habla con él después del ritual."}},
[7064]={"Corrupción de la tierra y de la semilla",{"Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace."}},
[7065]={"Corrupción de la tierra y de la semilla",{"Mata a la princesa Theradras y ve a ver al guardián Marandis a Punta de Nijel, en Desolace."}},
[7066]={"La semilla de la vida",{"Busca a Remulos en Claro de la Luna y dale la semilla de la vida."}},
[7067]={"Las instrucciones del Paria",{"Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace."}},
[7068]={"Fragmentos Oscuros",{"Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar."}},
[7070]={"Fragmentos Oscuros",{"Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango."}},
[7081]={"Los cementerios del Valle de Alterac",{"Asalta un cementerio y vuelve con el sargento Durgen Pico Tormenta en las Montañas de Alterac."}},
[7082]={"Los cementerios de Alterac",{"Asalta un cementerio y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac."}},
[7101]={"Las torres y los búnkeres",{"Captura una torre enemiga y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac."}},
[7102]={"Las torres y los búnkeres",{"Destruye el estandarte de una torre enemiga o de un búnker y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac."}},
[7121]={"El intendente",{"Habla con el intendente de Pico Tormenta."}},
[7122]={"Conquistar una mina",{"Captura una mina que no esté bajo control de los Pico Tormenta y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac."}},
[7123]={"Habla con nuestro intendente",{"Habla con el intendente de Lobo Gélido."}},
[7124]={"Conquistar una mina",{"Captura una mina y vuelve con el cabo Teeka Gruñidosangriento en las Montañas de Alterac."}},
[7141]={"La batalla de Alterac",{"Adéntrate en el Valle de Alterac, derrota al general Drek'thar de la Horda y vuelve junto a la prospectora Tallapiedra en las Montañas de Alterac."}},
[7142]={"La batalla por Alterac",{"Adéntrate en el Valle de Alterac y derrota al general enano Vanndar Pico Tormenta. Vuelve entonces junto a Voggah Agarre Letal en las Montañas de Alterac."}},
[7161]={"Terreno de pruebas",{"Viaja hasta la cueva Zarpa Salvaje ubicada al sureste del campamento base en el Valle de Alterac y encuentra el estandarte de los Lobo Gélido. Devuélvele el estandarte al maestro de guerra Laggrond."}},
[7162]={"Terreno de pruebas",{"Viaja hasta la cueva Ala Gélida ubicada al suroeste de Dun Baldar en el Valle de Alterac y recupera el estandarte de Pico Tormenta. Devuélveselo al teniente Haggerdin en las Montañas de Alterac."}},
